        for(int i(0);i<n;++i) cin>>arr[i];
        int sum[n]={0};
        int c[n]={0}; // counts the number of zeros from i to n-1
        sum[n-1]=arr[n-1];
        int ct=0; // counts number of zeros
        long long ans=0;
        for(int i(n-1);i>=0;--i){
            if(i!=(n-1)){
                sum[i]=(arr[i]+sum[i+1]);
                c[i]=c[i+1];
            }
            if(sum[i]>x) sum[i]=0;
            if(sum[i]==0){
                ++ct;
                c[i]=ct;
            }
        }
        for(int i(0);i<n;++i){
            ans+=(n-c[i]-i);
        }

        cout<<ans<<endl;
    }

    return 0;
}

